from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(4,'english','fit-body-fit-mind-fit-nation','Fit Body, Fit Mind, Fit Nation',
 ('Children who love to play','A rhyming poem introduces cheerful children: Anant the hockey player, Geeta the skater, Lhamo and his guitar, Shabana the cyclist and Meena who sings in rhythm. Each child is described with a word that starts with the same letter as their name. In this chapter you will read the poem, learn describing words (adjectives), find rhymes and double letters, and learn about the Paralympic Games.'),
 [('The poem and the children',['The poem introduces children who enjoy sports and music, each with a describing word before their name.','Active Anant plays hockey even when the ground is rocky. Graceful Geeta skates and learns every day from her mistakes.','Little Lhamo proudly plays the guitar while his friend plays the sitar. Swift Shabana celebrates after winning a cycle race at her fastest pace.','Musical Meena sings in rhythm, and cheerful children everywhere find playing a joy.','The title says that a fit body, a fit mind and a fit nation go together: when children play and stay healthy, the whole country grows strong.']),
  ('Why games and music matter',['Games and exercise keep our body strong and our mind alert.','Music and dance help us move in rhythm and feel happy.','Learning from mistakes, as Geeta does, helps us improve every day.','You can ask yourself which game you like and whether you enjoy indoor or outdoor games more.']),
  ('New words',['Mistakes are things done wrongly. Proudly means with a feeling of pride.','Pace is the speed at which we move. Rhythm is a regular beat in music or movement.','Cheerful means happy. Swift means very fast.']),
  ('Adjectives: words that describe',['A word that tells more about a noun is called an adjective.','Blue sky, hardworking children, green leaves, pebbled road and healthy vegetables are examples.','Happy child, red apple, fierce lion and beautiful flower show how an adjective goes before the noun.','You can add your own: sweet mangoes, cute baby, proud nation and clever winner.']),
  ('Rhymes and double letters',['Rhyming words have the same ending sound. Hockey and rocky rhyme. Skates and mistakes rhyme.','Guitar rhymes with sitar. Race rhymes with pace. Joy rhymes with boy.','Some words have a double letter, like village, ball, carrot, apple, kitchen and butter.']),
  ('Match the meanings',['Proudly means feeling happy about something you did well. Brave means courageous and bold.','Rocky means uneven or full of difficulties. Delightful means very pleasing or enjoyable.','Mistakes are errors, or things done incorrectly.']),
  ('Paralympic Games',['The Paralympic Games are an international sports event for athletes with physical disabilities.','They show that determination and practice matter more than anything, and they are held after the Olympic Games.','Find out about Indian Paralympic athletes and share what you learn with the class.','You can also try Preparing a Dish Without Fire, such as a fruit salad or a sandwich, with your teacher\'s help.'])],
 [('Pick the adjective: The healthy vegetables are green.',[('An adjective tells more about a noun.','It describes a thing.'),('Healthy and green describe the vegetables.','They tell how the vegetables are.'),('So healthy and green are adjectives.','Vegetables is the noun.')]),
  ('Find the rhyme for rocky.',[('Rocky ends with the sound ocky.','Listen to the ending.'),('Hockey has the same ending.','Hockey and rocky rhyme.'),('So the rhyme is hockey.','Rhymes share the last sound.')])],
 ('Explain what the poem says about children and why a fit body helps a fit nation.',['Children play games and music','Active, graceful, swift and cheerful','Learning from mistakes','Healthy children make a strong nation'],['Only winners matter','Music is not important']),
 ['Children in the poem enjoy hockey, skating, cycling, music and singing.','An adjective tells more about a noun.','Rhyming words end with the same sound.','Paralympic Games are for athletes with disabilities.','A fit body and mind make a fit nation.'],
 [M('1',1,'Which game does Anant play?','Hockey',[('Cricket','The poem says hockey'),('Football','The poem says hockey')],'Active Anant plays hockey.'),
  M('2',1,'Which musical instruments are in the poem?','Guitar and sitar',[('Drum and flute','Not in the poem'),('Piano and violin','Not in the poem')],'Lhamo plays the guitar and his friend the sitar.'),
  M('3',1,'Who learns every day from mistakes on skates?','Geeta',[('Meena','Meena sings'),('Shabana','Shabana cycles')],'Graceful Geeta practises on her skates.'),
  M('4',1,'Who sings in rhythm?','Meena',[('Geeta','Geeta skates'),('Anant','Anant plays hockey')],'Musical Meena sings in rhythm.'),
  M('5',2,'Which word is an adjective?','Hardworking',[('Children','Children is a noun'),('Plays','Plays is an action')],'Hardworking describes children.'),
  M('6',2,'What does proudly mean?','Feeling happy about something done well',[('Feeling lazy','Not the meaning'),('Feeling afraid','Not the meaning')],'Proudly shows pride.'),
  M('7',2,'What does rocky mean?','Uneven or difficult',[('Soft','Not the meaning'),('Smooth','The opposite')],'A rocky ground is uneven.'),
  M('8',2,'Which word rhymes with race?','Pace',[('Skates','Different ending'),('Guitar','Different ending')],'Race and pace share the sound.'),
  M('9',2,'Which word has a double letter?','Village',[('Lemon','No double letter'),('Mango','No double letter')],'Village has ll.'),
  M('10',2,'The Paralympic Games are for ___.','athletes with disabilities',[('only children','Not only children'),('only musicians','They are sports')],'They are a sports event for athletes with disabilities.'),
  F('11',2,'Shabana won a cycle race.',True,'She celebrated her fastest pace.'),
  S('12',3,'What word describes a noun?',['adjective','an adjective'],'An adjective describes a noun.')],
 keep=['adjective','rhythm'])
chapter(4,'english','the-lagori-champions','The Lagori Champions',
 ('A game of seven stones','Prakash visits his cousin Ravi and learns about Lagori, a game of seven flat stones, called Satoliya in his home state of Rajasthan. The next day the Sundarpur Tigers play the Green Warriors and win. In this chapter you will read the play, learn about traditional games, rearrange words into sentences, tell a sentence from a question and build a team badge.'),
 [('Part I: Meeting Prakash',['Ravi and his cousin Prakash go to the children\'s park, where friends are talking about tomorrow\'s Lagori match.','The friends want Prakash in the team because he is a quick runner.','Prakash has never heard of Lagori, so everyone looks at him in surprise, and Nidhi explains that it is a game of seven stones.','Imran, a champion of the game, explains how it is played.']),
  ('How Lagori is played',['Seven flat stones are stacked one above the other in the centre of the field.','One team knocks down the stones with a ball, and then the same team tries to rebuild the stack.','The other team throws the ball at the builders to stop them.','The field has a boundary line and players must not go beyond it.','Prakash says that in Rajasthan the same game is called Satoliya, so one game can have different names in different places.']),
  ('Part II: The match',['The next day the referee blew the whistle and Deepa took the first shot, scattering the stones and making everyone cheer.','The Sundarpur Tigers began to rebuild the stack while the Green Warriors threw the ball at them. Ravi ducked and Deepa dodged just in time.','Nidhi placed the fourth and fifth stones and Ravi placed the sixth, and Prakash set the seventh stone on top just before the final whistle.','The referee announced that the Sundarpur Tigers had won.']),
  ('Sportsmanship',['Both teams shook hands and appreciated each other, and the villagers cheered for both teams.','The referee lifted the hands of both captains because a good game is about teamwork and fair play, not only winning.','Deepa said it was even better than video games, and Ravi said they should play traditional games more.']),
  ('New words',['A match is a game played between teams. Stacked means piled one above the other.','An opponent is a person or team you play against. A boundary is a line that marks the edge.','A referee is the person who controls the game. Dodged means moved quickly to avoid something.','Teamwork is working together. Warriors are brave fighters. A cousin is the child of your uncle or aunt.']),
  ('Sentences and questions',['A sentence is a group of words that makes complete sense. It starts with a capital letter and usually ends with a full stop.','Rearrange the words: The field is marked with a boundary. Everybody looked at Prakash with surprise. I saw a peacock dancing in the rain.','A question asks something. It starts with a capital letter and ends with a question mark.','What is your name? and Where do you stay? are questions. My name is Sonam is a sentence that tells something.']),
  ('Activities',['Make a team badge with a name like Rainbow Runners and symbols like stacked stones, a ball or joined hands, and explain what it means.','Talk about a community game played in your colony or village and whether you took part.','Ask people at home about traditional games and learn one.'])],
 [('Make a sentence: boundary / field / is / the / marked / a / with.',[('Look for the subject.','The field is what we talk about.'),('Say what is done to it: is marked with a boundary.','Put the words in a sensible order.'),('So: The field is marked with a boundary.','Start with a capital letter and end with a full stop.')]),
  ('Is this a sentence or a question: Where do you stay?',[('Does it ask something?','It asks about a place.'),('It ends with a question mark.','Questions end with ?.'),('So it is a question.','My name is Sonam is a sentence.')])],
 ('Tell the story of the Lagori match and say why both captains were cheered.',['Lagori uses seven flat stones','The Tigers played the Warriors','Prakash placed the seventh stone','Teamwork and fair play matter'],['Only one team was cheered','Prakash played for Green Warriors']),
 ['Lagori is a game of seven flat stones, also called Satoliya.','The Sundarpur Tigers beat the Green Warriors.','Prakash set the seventh stone on top.','Both teams were cheered for fair play.','A sentence tells something; a question asks something.'],
 [M('1',1,'Who joined the group at the end?','Imran',[('Deepa','She was there before'),('Nidhi','She was there before')],'Imran joined and explained the game.'),
  M('2',1,'How many stones are used in Lagori?','Seven flat stones',[('Five round stones','Seven flat stones'),('Ten flat stones','Seven flat stones')],'Seven flat stones are stacked.'),
  M('3',1,'In which state is Lagori known as Satoliya?','Rajasthan',[('Kerala','Prakash said Rajasthan'),('Punjab','Prakash said Rajasthan')],'Prakash comes from there.'),
  M('4',1,'What is the name of the opponent team?','Green Warriors',[('Red Tigers','The opponent is Green Warriors'),('Blue Lions','The opponent is Green Warriors')],'Sundarpur Tigers played Green Warriors.'),
  M('5',1,'Who took the first shot?','Deepa',[('Ravi','Deepa took the first shot'),('Prakash','Prakash placed the last stone')],'Deepa threw the ball at the stack.'),
  M('6',1,'What did Prakash do before the final whistle?','Set the seventh stone on top',[('Threw the ball','He placed a stone'),('Blew the whistle','The referee did')],'That completed the stack.'),
  M('7',2,'What is a referee?','The person who controls the game',[('The captain','Not the meaning'),('The opponent','Not the meaning')],'A referee blows the whistle.'),
  M('8',2,'What is an opponent?','A person or team you play against',[('A friend on your team','Opposite meaning'),('The audience','Not the meaning')],'The Green Warriors were the opponents.'),
  M('9',2,'Which is a question?','Where do you stay?',[('My name is Sonam.','That is a sentence'),('This flower is beautiful.','That is a sentence')],'It asks and ends with a question mark.'),
  F('10',2,'Satoliya is played in Sundarpur village.',False,'Satoliya is the name in Rajasthan; Sundarpur says Lagori.'),
  F('11',2,'The Sundarpur Tigers won the match.',True,'The referee announced it.'),
  M('12',3,'Why did the villagers cheer both teams?','Fair play and teamwork matter',[('Both teams won','The Tigers won'),('They did not know who won','They knew')],'A good game is about teamwork.')],
 keep=['Lagori','referee'])
